PROGRAM ST050_INDEXMATARE
VAR
    steg        : INT := 0;
    tmrIndex    : TON;
    trigReset   : R_TRIG;
    xLarm       : BOOL := FALSE;
    xKravOmstart: BOOL := TRUE;
    xDriftsklar : BOOL := FALSE;
END_VAR

(* EMG_OK kommer fran sakerhets-PLC och lases bara. Den har logiken ror inte
   sjalva sakerhetsfunktionen; den ar forreglad AV den. *)
trigReset(CLK := SYS_RESET);

(* --- alla larmkallor samlas fore domen, sa SYS_ALARM aldrig slapar ett scan
       efter det don den ska stoppa. --- *)

(* Ett brutet nodstopp kraver en manuell kvittering innan stationen far ga
   igen. Att slappa upp nodstoppsdonet startar ingenting. *)
IF NOT EMG_OK THEN
    xKravOmstart := TRUE;
END_IF;

(* Lagesgivaren utanfor arbetsomradet 0 till 300 mm ar i sig ett larm: en
   matare som rapporterar ett lage den inte kan sta i har tappat sin givare. *)
IF ST050_IDX_POS < 0.0 OR ST050_IDX_POS > 300.0 THEN
    xLarm := TRUE;
END_IF;

(* Tidsovervakningen. Indexet ska vara klart inom 2,0 s; kommer inte
   ST050_IDX_DONE har nagot fastnat och stationen far inte fortsatta. *)
tmrIndex(IN := ST050_IDX_START, PT := T#2s);
IF tmrIndex.Q THEN
    xLarm := TRUE;
END_IF;

(* Klamman far inte slappa mitt i rorelsen. Gor den det ar detaljen los. *)
IF steg = 2 AND NOT ST050_CLP_CLOSED THEN
    xLarm := TRUE;
END_IF;

(* Aterstallning kraver en stigande flank pa SYS_RESET och att nodstoppet ar
   aterstallt. Larmet slapper aldrig av sig sjalvt. *)
IF trigReset.Q AND EMG_OK AND AIR_OK THEN
    xLarm := FALSE;
    xKravOmstart := FALSE;
END_IF;

SYS_ALARM := xLarm;
xDriftsklar := EMG_OK AND AIR_OK AND SYS_AUTO AND NOT xLarm AND NOT xKravOmstart;

IF NOT xDriftsklar THEN
    ST050_CNV_RUN := FALSE;
    ST050_IDX_START := FALSE;
    ST050_CLP_CLOSE := FALSE;
    steg := 0;
ELSE
    ST050_CNV_RUN := TRUE;
    CASE steg OF
        0:
            ST050_IDX_START := FALSE;
            IF ST050_PRT_PRS THEN
                ST050_CLP_CLOSE := TRUE;
                steg := 1;
            END_IF;
        1:
            IF ST050_CLP_CLOSED THEN
                ST050_IDX_START := TRUE;
                steg := 2;
            END_IF;
        2:
            IF ST050_IDX_DONE THEN
                ST050_IDX_START := FALSE;
                ST050_CLP_CLOSE := FALSE;
                steg := 3;
            END_IF;
        3:
            IF NOT ST050_CLP_CLOSED THEN
                steg := 0;
            END_IF;
    ELSE
        steg := 0;
    END_CASE;
END_IF;
END_PROGRAM

